INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(11441, 0, 0, 'Raaar!!! Me smash $r!', 12, 0, 100, 0, 0, 0, 'Gordok Brute'),
(11441, 0, 1, 'Me smash! You die!', 12, 0, 100, 0, 0, 0, 'Gordok Brute'),
(11441, 0, 2, 'I''ll crush you!', 12, 0, 100, 0, 0, 0, 'Gordok Brute'),
(11441, 1, 0, '%s becomes enraged!', 16, 0, 100, 0, 0, 0, 'Gordok Brute'),
(11442, 0, 0, 'Raaar!!! Me smash $r!', 12, 0, 100, 0, 0, 0, 'Gordok Mauler'),
(11442, 0, 1, 'Me smash! You die!', 12, 0, 100, 0, 0, 0, 'Gordok Mauler'),
(11442, 0, 2, 'I''ll crush you!', 12, 0, 100, 0, 0, 0, 'Gordok Mauler'),
(11442, 1, 0, '%s becomes enraged!', 16, 0, 100, 0, 0, 0, 'Gordok Mauler'),
(11444, 0, 0, 'Raaar!!! Me smash $r!', 12, 0, 100, 0, 0, 0, 'Gordok Mage-Lord'),
(11444, 0, 1, 'Me smash! You die!', 12, 0, 100, 0, 0, 0, 'Gordok Mage-Lord'),
(11444, 0, 2, 'I''ll crush you!', 12, 0, 100, 0, 0, 0, 'Gordok Mage-Lord'),
(11444, 1, 0, '%s becomes enraged!', 16, 0, 100, 0, 0, 0, 'Gordok Mage-Lord'),
(11448, 0, 0, 'Raaar!!! Me smash $r!', 12, 0, 100, 0, 0, 0, 'Gordok Warlock'),
(11448, 0, 1, 'Me smash! You die!', 12, 0, 100, 0, 0, 0, 'Gordok Warlock'),
(11448, 0, 2, 'I''ll crush you!', 12, 0, 100, 0, 0, 0, 'Gordok Warlock'),
(11469, 0, 0, '%s becomes enraged!', 16, 0, 100, 0, 0, 0, 'Eldreth Seether'),
(11486, 0, 0, 'Who dares disrupt the sanctity of Eldre''Thalas? Face me, cowards!', 14, 0, 100, 0, 0, 0, 'Prince Tortheldrin'),
(11496, 0, 0, '%s goes into a frenzy!', 16, 0, 100, 0, 0, 0, 'Immol''thar'),
(11501, 0, 0, 'You no challenge me, scrubs!  I''m da king now, and I stay king FOREVER!!!', 12, 0, 100, 0, 0, 0, 'King Gordok to Player'),
(14321, 0, 0, '%s goes into a frenzy!', 16, 0, 100, 0, 0, 0, 'Guard Fengus'),
(14322, 0, 0, '%s goes into a frenzy!', 16, 0, 100, 0, 0, 0, 'Stomper Kreeg'),
(14323, 0, 0, '%s goes into a frenzy!', 16, 0, 100, 0, 0, 0, 'Guard Slip''kik'),
(14325, 0, 0, 'No one get past me and threaten da king!  Ungh, take it!!', 12, 0, 100, 0, 0, 0, 'Captain Kromcrush'),
(14325, 1, 0, 'Help me crush these punys!', 14, 0, 100, 0, 0, 0, 'Captain Kromcrush'),
(14325, 2, 0, '%s begins to retaliate all attacks against him!', 16, 0, 100, 0, 0, 0, 'Captain Kromcrush'),
(14325, 3, 0, 'Hey, who Fengus callin'' a gnoll lover?!  Take da prisoners to da king; you smart to bring them with their weapons and show da king that they a threat.  I''ll go see if Fengus talk smack when I give him da beatdown!  HAR!', 12, 0, 100, 0, 0, 0, 'Captain Kromcrush'),
(14325, 4, 0, 'OK Fengus, where you at?!  You come call me a gnoll lover while I give you da hammer upside da head!', 14, 0, 100, 0, 0, 0, 'Captain Kromcrush'),
(14326, 0, 0, '%s goes into a frenzy!', 16, 0, 100, 0, 0, 0, 'Guard Mol''dar'),
(14353, 0, 0, 'OH NOES!  Da king is dead!  Uh... hail to da new king!  Yeah!', 14, 0, 100, 0, 0, 0, 'Mizzle the Crafty to 58960'),
(14353, 1, 0, 'Yar, he''s dead all right.  That makes you da new king... well, all of you!  Gordok is yours now, boss!  You should talk to me so you can learn everything there is about being da king!  I was... is his assistant!  Yeah, that''s why I''m called da crafty one!', 12, 0, 100, 0, 0, 0, 'Mizzle the Crafty to 58960');
