-- Dire Maul (map 429): SmartAI, texts and the Gordok Tribute chain from 4.3.4 (Dire Maul was re-levelled by Cataclysm, so 4.3.4 is the
-- reference; 3.3.5 has the same scripts). 51 creatures get their SmartAI (274 rows), plus Stomper Kreeg's timed action list (3 rows)
-- and the two gameobject scripts (4 rows). Columns are identical to SkyFire's; event_flags are kept (0x2 normal) except for the 4.3.4
-- WHILE_CHARMED bit (0x200), which is the 40-man difficulty bit in SkyFire.
-- Mizzle the Crafty and Cho'Rush get their gossip back (npcflag and gossip menu; the menus, options and npc_text rows already exist).
-- Safe to run twice: DELETE before INSERT by key, guarded template updates.

-- Enable SmartAI only where no C++ script is bound.
UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `entry` IN (11441, 11442, 11444, 11445, 11446, 11448, 11450, 11453, 11458, 11459, 11461, 11464, 11465, 11466, 11467, 11469, 11470, 11471, 11472, 11473, 11475, 11476, 11480, 11483, 11484, 11486, 11487, 11488, 11489, 11490, 11492, 11496, 11501, 13036, 13160, 13276, 13280, 13285, 14303, 14321, 14322, 14323, 14324, 14325, 14326, 14327, 14349, 14351, 14353, 14386, 16045) AND `ScriptName` = '';
UPDATE `gameobject_template` SET `AIName` = 'SmartGameObjectAI' WHERE `entry` IN (179485, 179499) AND `AIName` = '' AND `ScriptName` = '';

-- Mizzle the Crafty (14353) and Cho'Rush the Observer (14324): gossip, as in 4.3.4.
UPDATE `creature_template` SET `npcflag` = 1, `gossip_menu_id` = 5708 WHERE `entry` = 14353 AND `npcflag` = 0 AND `gossip_menu_id` = 0;
UPDATE `creature_template` SET `npcflag` = 1, `gossip_menu_id` = 5742 WHERE `entry` = 14324 AND `npcflag` = 0 AND `gossip_menu_id` = 0;

-- Texts (SkyFire has none for these entries).
DELETE FROM `creature_text` WHERE `entry` IN (11441, 11442, 11444, 11448, 11469, 11486, 11496, 11501, 14321, 14322, 14323, 14325, 14326, 14353);

-- Creature SmartAI rows.
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND `entryorguid` IN (11441, 11442, 11444, 11445, 11446, 11448, 11450, 11453, 11458, 11459, 11461, 11464, 11465, 11466, 11467, 11469, 11470, 11471, 11472, 11473, 11475, 11476, 11480, 11483, 11484, 11486, 11487, 11488, 11489, 11490, 11492, 11496, 11501, 13036, 13160, 13276, 13280, 13285, 14303, 14321, 14322, 14323, 14324, 14325, 14326, 14327, 14349, 14351, 14353, 14386, 16045);

-- Stomper Kreeg timed action list (called by his out of combat row).
DELETE FROM `smart_scripts` WHERE `source_type` = 9 AND `entryorguid` = 1432200;

-- Gameobject scripts: Broken Trap (179485) and Ogre Tannin Basket (179499).
DELETE FROM `smart_scripts` WHERE `source_type` = 1 AND `entryorguid` IN (179485, 179499);
